CREATE TABLE dev_meta.catalogue_state (singleton INT PRIMARY KEY CHECK(singleton=1), revision BIGINT NOT NULL DEFAULT 0, rules CHARACTER LARGE OBJECT NOT NULL);
INSERT INTO dev_meta.catalogue_state VALUES(1,0,'{"categoryExtras":{},"swapGroups":{},"items":{},"combos":{}}');
CREATE TABLE dev_meta.import_receipt (source_hash VARCHAR(64) PRIMARY KEY, applied_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE dev_meta.module_events (event_id UUID PRIMARY KEY, command_id UUID NOT NULL, action VARCHAR(80) NOT NULL, entity_id UUID, revision BIGINT NOT NULL, payload CHARACTER LARGE OBJECT NOT NULL, recorded_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, seq BIGINT GENERATED ALWAYS AS IDENTITY UNIQUE);
CREATE TABLE dev_meta.outbox (event_id UUID PRIMARY KEY REFERENCES dev_meta.module_events(event_id), body CHARACTER LARGE OBJECT NOT NULL, state VARCHAR(20) NOT NULL DEFAULT 'PENDING_DISABLED');
CREATE TABLE dev_meta.customer_identity (customer_id UUID PRIMARY KEY, source_id BIGINT NOT NULL UNIQUE REFERENCES public.customers(id), revision BIGINT NOT NULL DEFAULT 0, archived BOOLEAN NOT NULL DEFAULT FALSE, banned BOOLEAN NOT NULL DEFAULT FALSE, ban_reason CHARACTER LARGE OBJECT, ban_changed_at TIMESTAMP WITH TIME ZONE, updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, canonical_id UUID REFERENCES dev_meta.customer_identity(customer_id), sync_state VARCHAR(30) NOT NULL DEFAULT 'PENDING_DISABLED');
CREATE TABLE dev_meta.customer_status (id UUID PRIMARY KEY, customer_id UUID NOT NULL REFERENCES dev_meta.customer_identity(customer_id), action VARCHAR(20) NOT NULL, reason CHARACTER LARGE OBJECT, recorded_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE dev_meta.customer_conflicts (id UUID PRIMARY KEY, revision BIGINT NOT NULL DEFAULT 0, payload CHARACTER LARGE OBJECT NOT NULL, reason VARCHAR(100) NOT NULL, state VARCHAR(20) NOT NULL DEFAULT 'OPEN', resolution CHARACTER LARGE OBJECT);
CREATE TABLE dev_meta.drafts (order_id UUID PRIMARY KEY, reference VARCHAR(64) NOT NULL UNIQUE, revision BIGINT NOT NULL DEFAULT 0, status VARCHAR(20) NOT NULL DEFAULT 'DRAFT', customer_id UUID REFERENCES dev_meta.customer_identity(customer_id), snapshot CHARACTER LARGE OBJECT NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
